#!/usr/bin/env python3
"""Generate dummy.urdf and its visual meshes for the IDC2026 mannequin.

Run from anywhere:  python3 gen_dummy.py [--out DIR]

Produces
    <out>/dummy.urdf
    <out>/meshes/*.obj      visual geometry, metres, one mesh per file

Design decisions (see conversation log / dummy_params.py):
  * Visual geometry is generated by revolving traced 2-D profiles (lathe),
    optionally flattened on one axis.  This gets the silhouette right, which
    is what a detector sees, without hand-sculpting.
  * Collision geometry is URDF primitives only (box / cylinder / sphere).
    Primitives are convex by definition, so MuJoCo never has to compute a
    hull, and the MJCF patch step upgrades cylinders to capsules.
  * Ball joints (shoulders, hips, waist) become three stacked revolute joints
    ordered Z (twist) -> X -> Y with zero-length massless intermediate links,
    because URDF has no ball joint.
  * Root link is the pelvis.  The rulebook pins the pelvis to the goal's top
    surface, so that is the natural base frame for pose sampling.

Frame convention: ROS standard, +X forward (facing), +Y to the figure's left,
+Z up.  Zero pose is standing with arms down and legs straight.
"""

import argparse
import math
import os

from dummy_params import (
    D, PROFILES, DEPTH_RATIO, FLATTEN, LIMITS, WOOD_DENSITY, BALL_FRAC,
    SHOULDER_FRAC_OF_CHEST, HIP_FRAC_OF_PELVIS, STANDING_HEIGHT_MM,
)

N_SEG = 48  # segments around the revolution axis

# Effective density, solved in main() so the finished model weighs exactly
# TARGET_MASS_G.  The mass is the number we were given; the density is not,
# so the density is what gets adjusted.  Adding the joint balls raised the
# geometric volume, and holding WOOD_DENSITY fixed would have quietly pushed
# the figure to 161 g -- 35 % heavy, which scales straight into every
# calibrated frictionloss.
DENSITY = WOOD_DENSITY
TARGET_MASS_G = 119.0


# --------------------------------------------------------------------------
# mesh generation
# --------------------------------------------------------------------------

def _resample(profile, n=40):
    """Linearly resample [(t, r), ...] to n evenly spaced t values."""
    out = []
    for i in range(n):
        t = i / (n - 1)
        for j in range(len(profile) - 1):
            t0, r0 = profile[j]
            t1, r1 = profile[j + 1]
            if t0 <= t <= t1:
                f = 0.0 if t1 == t0 else (t - t0) / (t1 - t0)
                out.append((t, r0 + f * (r1 - r0)))
                break
        else:
            out.append((t, profile[-1][1]))
    return out


def lathe(profile, length, radius, scale_x=1.0, scale_y=1.0, n_along=40):
    """Revolve a profile about +Z.

    profile   [(t, r)] with t and r normalised to [0, 1]
    length    extent along +Z, metres
    radius    max radius, metres
    scale_x/y anisotropic squash applied after revolving (for flat paddles
              and for torso parts that are wider than they are deep)

    Returns (verts, faces) with faces as 0-indexed triangles.
    """
    pts = _resample(profile, n_along)
    verts, faces, uvs = [], [], []

    # Ring vertices, skipping degenerate rings (r == 0) which become poles.
    # UVs come free from the lathe parameterisation: u is the angle around the
    # axis, v is the position along it.  That is a clean cylindrical unwrap,
    # which is what wood grain and worn paint want.
    ring_start = {}
    for i, (t, r) in enumerate(pts):
        z = t * length
        if r <= 1e-9:
            ring_start[i] = ("pole", len(verts))
            verts.append((0.0, 0.0, z))
            uvs.append((0.5, t))
            continue
        ring_start[i] = ("ring", len(verts))
        for s in range(N_SEG):
            a = 2.0 * math.pi * s / N_SEG
            x = r * radius * math.cos(a) * scale_x
            y = r * radius * math.sin(a) * scale_y
            verts.append((x, y, z))
            uvs.append((s / N_SEG, t))

    def quad(a, b, c, d):
        faces.append((a, b, c))
        faces.append((a, c, d))

    for i in range(len(pts) - 1):
        k0, b0 = ring_start[i]
        k1, b1 = ring_start[i + 1]
        if k0 == "ring" and k1 == "ring":
            for s in range(N_SEG):
                s2 = (s + 1) % N_SEG
                quad(b0 + s, b0 + s2, b1 + s2, b1 + s)
        elif k0 == "pole" and k1 == "ring":
            for s in range(N_SEG):
                s2 = (s + 1) % N_SEG
                faces.append((b0, b1 + s2, b1 + s))
        elif k0 == "ring" and k1 == "pole":
            for s in range(N_SEG):
                s2 = (s + 1) % N_SEG
                faces.append((b0 + s, b0 + s2, b1))

    # Cap flat ends.
    for i, sgn in ((0, -1), (len(pts) - 1, +1)):
        kind, base = ring_start[i]
        if kind != "ring":
            continue
        z = pts[i][0] * length
        c = len(verts)
        verts.append((0.0, 0.0, z))
        uvs.append((0.5, pts[i][0]))
        for s in range(N_SEG):
            s2 = (s + 1) % N_SEG
            if sgn < 0:
                faces.append((c, base + s2, base + s))
            else:
                faces.append((c, base + s, base + s2))

    return verts, faces, uvs


def profile_centroid(profile, length, n=400):
    """Axial centroid of a solid of revolution, metres from its base.

    A lathe body's centre of mass lies on its axis at

        z_bar = Int r(z)^2 z dz / Int r(z)^2 dz

    Anisotropic squashing scales x and y uniformly along the length, so it
    leaves z_bar unchanged and this stays exact for the flattened parts too.
    """
    pts = _resample(profile, n)
    num = den = 0.0
    for i in range(len(pts) - 1):
        (t0, r0), (t1, r1) = pts[i], pts[i + 1]
        rm = 0.5 * (r0 + r1)
        zm = 0.5 * (t0 + t1) * length
        dz = (t1 - t0) * length
        w = rm * rm * dz
        num += w * zm
        den += w
    return num / den if den else 0.5 * length


def capsule_chain(profile, length, radius, sx=1.0, sy=1.0, n=5, base_z=0.0,
                  axis="z"):
    """Collision geometry inscribed inside a lathe body.

    The first version wrapped each torso part in a single box sized to its
    WIDEST ring and its FULL length, which is a brick: the arms started 2.2 mm
    inside the chest and the thighs 3.5 mm inside the pelvis at the zero pose,
    so every settle began with the solver shoving overlapping bodies apart.

    Instead, cut the profile into n bands and inscribe a capsule in each, using
    the band's MINIMUM radius so the capsule can never poke out through the
    visual surface.  Under-approximating is the safe direction: a limb that
    grazes the torso is far better than one that can never touch it.

    The capsule's cylindrical part is shortened by 2r so its hemispherical
    caps land exactly on the band's ends.  Forgetting that is what made the
    old cylinders overshoot their links by a full radius at each end.
    """
    pts = _resample(profile, 400)
    rmin = min(sx, sy)
    out = []
    for i in range(n):
        t0, t1 = i / n, (i + 1) / n
        band = [r for t, r in pts if t0 <= t <= t1]
        r = min(band) * radius * rmin if band else 0.0
        if r <= 1e-5:
            continue
        z0, z1 = base_z + t0 * length, base_z + t1 * length
        zc, L = 0.5 * (z0 + z1), z1 - z0
        pos = f"0 0 {zc:.5f}" if axis == "z" else f"{zc:.5f} 0 0"
        rpy = "0 0 0" if axis == "z" else f"0 {math.pi/2:.5f} 0"
        if L <= 2.0 * r:
            out.append((sph(r), pos, "0 0 0"))
        else:
            out.append((cyl(r, L - 2.0 * r), pos, rpy))
    return out


def mesh_volume(verts, faces):
    """Signed volume via the divergence theorem.  Metres cubed."""
    v = 0.0
    for a, b, c in faces:
        x1, y1, z1 = verts[a]
        x2, y2, z2 = verts[b]
        x3, y3, z3 = verts[c]
        v += (x1 * (y2 * z3 - y3 * z2)
              - x2 * (y1 * z3 - y3 * z1)
              + x3 * (y1 * z2 - y2 * z1))
    return abs(v) / 6.0


def write_stl(path, verts, faces, name):
    """Binary STL.

    This is what the URDF references.  STL carries no UVs, but it is the
    format both MuJoCo and CAD Viewer accept -- CAD Viewer's served-asset
    allowlist is .step/.stp/.stl/.3mf/.glb/.gcode/.dxf/.urdf/.srdf/.sdf, so a
    URDF pointing at .obj renders as "failed to render mesh".  The OBJ next to
    it keeps the UVs for Blender.
    """
    import struct
    with open(path, "wb") as f:
        f.write(f"IDC2026 {name}".ljust(80, " ").encode()[:80])
        f.write(struct.pack("<I", len(faces)))
        for a, b, c in faces:
            ax, ay, az = verts[a]
            bx, by, bz = verts[b]
            cx, cy, cz = verts[c]
            ux, uy, uz = bx - ax, by - ay, bz - az
            vx, vy, vz = cx - ax, cy - ay, cz - az
            nx, ny, nz = uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx
            L = math.sqrt(nx * nx + ny * ny + nz * nz) or 1.0
            f.write(struct.pack("<12fH", nx / L, ny / L, nz / L,
                                ax, ay, az, bx, by, bz, cx, cy, cz, 0))


def write_obj(path, verts, faces, uvs, name):
    """Triangulated OBJ with vertex normals and UVs, one object per file.

    Kept alongside the STL for Blender, which wants the UVs for wood grain and
    worn-paint texturing.  The URDF references the STL, not this.
    """
    normals = [[0.0, 0.0, 0.0] for _ in verts]
    for a, b, c in faces:
        ax, ay, az = verts[a]
        bx, by, bz = verts[b]
        cx, cy, cz = verts[c]
        ux, uy, uz = bx - ax, by - ay, bz - az
        vx, vy, vz = cx - ax, cy - ay, cz - az
        nx, ny, nz = uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx
        for i in (a, b, c):
            normals[i][0] += nx
            normals[i][1] += ny
            normals[i][2] += nz
    for n in normals:
        L = math.sqrt(n[0] ** 2 + n[1] ** 2 + n[2] ** 2) or 1.0
        n[0] /= L
        n[1] /= L
        n[2] /= L

    with open(path, "w") as f:
        f.write(f"# IDC2026 mannequin link '{name}' -- generated, metres\n")
        f.write(f"o {name}\n")
        for x, y, z in verts:
            f.write(f"v {x:.6f} {y:.6f} {z:.6f}\n")
        for u, v in uvs:
            f.write(f"vt {u:.6f} {v:.6f}\n")
        for nx, ny, nz in normals:
            f.write(f"vn {nx:.6f} {ny:.6f} {nz:.6f}\n")
        for a, b, c in faces:
            f.write(f"f {a+1}/{a+1}/{a+1} {b+1}/{b+1}/{b+1} {c+1}/{c+1}/{c+1}\n")


# --------------------------------------------------------------------------
# link specifications
# --------------------------------------------------------------------------

def scaled_dims(factor):
    """All dimensions scaled by `factor`, except the two measured directly.

    STANDING_HEIGHT_MM and SHOULDER_SPAN_MM are tape measurements and are
    slightly inconsistent with each other (3 %, see dummy_params).  We honour
    the height by scaling the photogrammetry chain, and honour the shoulder
    span by leaving it alone.
    """
    keep = {"shoulder_span", "shoulder_ball_r"}
    return {k: (v if k in keep else v * factor) for k, v in D.items()}


def build_meshes(mesh_dir, D):
    """Generate every visual mesh.  Returns {name: spec}.

    There is no neck mesh: on the real figure the neck is a small ball, so it
    is emitted as a sphere primitive on the chest instead (see build_urdf).
    """
    specs = {}

    def add(name, profile, length, radius, sx=1.0, sy=1.0, n=5):
        v, f, uv = lathe(PROFILES[profile], length, radius, sx, sy)
        write_obj(os.path.join(mesh_dir, f"{name}.obj"), v, f, uv, name)
        write_stl(os.path.join(mesh_dir, f"{name}.stl"), v, f, name)
        specs[name] = dict(
            volume=mesh_volume(v, f), length=length, radius=radius,
            cz=profile_centroid(PROFILES[profile], length),
            col=capsule_chain(PROFILES[profile], length, radius, sx, sy, n),
        )

    add("head", "head", D["head"], D["head_w"] / 2, 1.0, DEPTH_RATIO["head"], n=4)
    add("chest", "chest", D["chest"], D["chest_w"] / 2, 1.0, DEPTH_RATIO["chest"], n=6)
    add("pelvis", "pelvis", D["pelvis"], D["pelvis_w"] / 2, 1.0, DEPTH_RATIO["pelvis"], n=5)

    add("upper_arm", "spindle", D["upper_arm"], D["upper_arm_d"] / 2, n=4)
    add("forearm", "spindle", D["forearm"], D["forearm_d"] / 2, n=4)
    add("hand", "hand", D["hand"], D["hand_w"] / 2, 1.0, FLATTEN["hand"], n=3)

    add("thigh", "spindle", D["thigh"], D["thigh_d"] / 2, n=4)
    add("shin", "spindle", D["shin"], D["shin_d"] / 2, n=4)
    add("foot", "foot", D["foot"], D["foot_w"] / 2, 1.0, FLATTEN["foot"], n=3)

    return specs


# --------------------------------------------------------------------------
# URDF assembly
# --------------------------------------------------------------------------

class Urdf:
    def __init__(self, name):
        self.name = name
        self.parts = []

    def link(self, name, visuals=(), collisions=(), mass=1e-5, inertia=None,
             com="0 0 0"):
        ix, iy, iz = inertia or (1e-9, 1e-9, 1e-9)
        s = [f'  <link name="{name}">']
        s.append('    <inertial>')
        # The inertial origin is the link's centre of mass, NOT the link frame.
        # Omitting it lumps every link's mass at its own joint, which silently
        # zeroes the gravity lever arm for the hand, foot and head and makes
        # every joint torque in the model wrong.
        s.append(f'      <origin xyz="{com}" rpy="0 0 0"/>')
        s.append(f'      <mass value="{mass:.6e}"/>')
        s.append(f'      <inertia ixx="{ix:.6e}" ixy="0" ixz="0"'
                 f' iyy="{iy:.6e}" iyz="0" izz="{iz:.6e}"/>')
        s.append('    </inertial>')
        for mesh, origin, rpy in visuals:
            # A visual is either a mesh name or a ready-made primitive tag --
            # the joint balls are spheres, not lathe bodies.
            g = mesh if mesh.startswith("<") else f'<mesh filename="meshes/{mesh}.stl"/>'
            s.append('    <visual>')
            s.append(f'      <origin xyz="{origin}" rpy="{rpy}"/>')
            s.append('      <geometry>')
            s.append(f'        {g}')
            s.append('      </geometry>')
            s.append(f'      <material name="paint"/>')
            s.append('    </visual>')
        for geom, origin, rpy in collisions:
            s.append('    <collision>')
            s.append(f'      <origin xyz="{origin}" rpy="{rpy}"/>')
            s.append(f'      <geometry>{geom}</geometry>')
            s.append('    </collision>')
        s.append('  </link>')
        self.parts.append("\n".join(s))

    def joint(self, name, parent, child, xyz="0 0 0", rpy="0 0 0",
              axis=None, limit=None):
        jtype = "fixed" if axis is None else "revolute"
        s = [f'  <joint name="{name}" type="{jtype}">']
        s.append(f'    <parent link="{parent}"/>')
        s.append(f'    <child link="{child}"/>')
        s.append(f'    <origin xyz="{xyz}" rpy="{rpy}"/>')
        if axis is not None:
            s.append(f'    <axis xyz="{axis}"/>')
            lo, hi = limit
            s.append(f'    <limit lower="{lo:.5f}" upper="{hi:.5f}"'
                     f' effort="5" velocity="10"/>')
            # Wooden joints have real stiction -- they hold a pose.  This is
            # the URDF-portable hint; MuJoCo gets proper frictionloss in the
            # MJCF patch step, which is what actually makes the figure hold.
            s.append('    <dynamics damping="0.002" friction="0.004"/>')
        s.append('  </joint>')
        self.parts.append("\n".join(s))

    def dumps(self, mujoco_block=True):
        head = [f'<?xml version="1.0"?>',
                f'<robot name="{self.name}">']
        if mujoco_block:
            head += [
                '  <!-- MuJoCo reads this extension block and ignores it',
                '       elsewhere.  Lets MjModel.from_xml_path() load this',
                '       URDF directly with no preprocessing. -->',
                '  <mujoco>',
                '    <compiler meshdir="." balanceinertia="true"',
                '              discardvisual="false" strippath="false"/>',
                '  </mujoco>',
                '  <material name="paint">',
                '    <color rgba="0.78 0.78 0.80 1"/>',
                '  </material>',
            ]
        return "\n".join(head + self.parts + ['</robot>', ''])


def inertia_box(mass, dx, dy, dz):
    k = mass / 12.0
    return (k * (dy * dy + dz * dz), k * (dx * dx + dz * dz), k * (dx * dx + dy * dy))


def cyl(r, l):
    return f'<cylinder radius="{r:.5f}" length="{l:.5f}"/>'


def box(x, y, z):
    return f'<box size="{x:.5f} {y:.5f} {z:.5f}"/>'


def sph(r):
    return f'<sphere radius="{r:.5f}"/>'


def ball_chain(u, parent, child, base, xyz, rpy, key):
    """Three stacked revolute joints standing in for a ball joint.

    Ordered Z (twist) -> X -> Y.  The two intermediate links are zero-length
    and effectively massless.  Limits keep the middle axis well inside
    +-90 deg so the gimbal singularity is never reachable.
    """
    l1, l2 = f"{base}_i1", f"{base}_i2"
    u.link(l1)
    u.link(l2)
    u.joint(f"{base}_z", parent, l1, xyz=xyz, rpy=rpy,
            axis="0 0 1", limit=LIMITS[f"{key}_z"])
    u.joint(f"{base}_x", l1, l2, axis="1 0 0", limit=LIMITS[f"{key}_x"])
    u.joint(f"{base}_y", l2, child, axis="0 1 0", limit=LIMITS[f"{key}_y"])


def shift(col, dz):
    """Translate a collision chain along its own +Z."""
    out = []
    for geom, pos, rpy in col:
        x, y, z = (float(v) for v in pos.split())
        out.append((geom, f"{x:.5f} {y:.5f} {z + dz:.5f}", rpy))
    return out


def to_x(col):
    """Rotate a collision chain so the mesh's +Z points along the link's +X.

    Used for the feet, whose visual carries the same Ry(pi/2).  The collision
    has to follow the visual or the foot collides where it is not drawn.
    """
    out = []
    for geom, pos, rpy in col:
        _, y, z = (float(v) for v in pos.split())
        # Capsules are axis-aligned to their own +Z, so they need the rotation
        # too; spheres do not care.
        r = f"0 {math.pi/2:.5f} 0" if "cylinder" in geom else "0 0 0"
        out.append((geom, f"{z:.5f} {y:.5f} 0", r))
    return out


def ball(r):
    """A visible joint ball: same sphere used as visual and as collision."""
    return sph(r)


def sphere_volume(r):
    return 4.0 / 3.0 * math.pi * r ** 3


class Mass:
    """Accumulates mass and centre of mass over a link's several pieces.

    Needed once the joint balls became real geometry: a link is no longer one
    lathe body, and lumping the balls in without moving the COM would put the
    gravity lever back in the wrong place -- the same class of bug that made
    every joint torque wrong the first time round.
    """

    def __init__(self):
        self.m = 0.0
        self.mx = [0.0, 0.0, 0.0]

    def add(self, mass, com=(0.0, 0.0, 0.0)):
        self.m += mass
        for i in range(3):
            self.mx[i] += mass * com[i]
        return self

    @property
    def com(self):
        if self.m <= 0:
            return "0 0 0"
        return " ".join(f"{v / self.m:.5f}" for v in self.mx)


def build_urdf(specs, D):
    u = Urdf("idc2026_dummy")
    dens = DENSITY

    def mass_of(name):
        return dens * specs[name]["volume"]

    def ball_mass(r):
        return dens * sphere_volume(r)

    # --- visible joint balls, radii from BALL_FRAC (see dummy_params) ------
    r_neck = BALL_FRAC["neck"] * D["head_w"]
    r_waist = BALL_FRAC["waist"] * D["pelvis_w"]
    r_hip = BALL_FRAC["hip"] * D["pelvis_w"]
    r_shldr = D["shoulder_ball_r"]          # tape-measured, held absolute
    r_elbow = BALL_FRAC["elbow"] * D["upper_arm_d"]
    r_wrist = BALL_FRAC["wrist"] * D["forearm_d"]
    r_knee = BALL_FRAC["knee"] * D["thigh_d"]
    r_ankle = BALL_FRAC["ankle"] * D["shin_d"]

    # ---- pelvis (root).  Link frame at the hip centre line, +Z up. --------
    # Carries the two hip balls and the waist ball, so the sockets are never
    # left as an open gap between two butt-joined lathe bodies.
    pel_len, pel_w = D["pelvis"], D["pelvis_w"]
    pel_off = -HIP_FRAC_OF_PELVIS * pel_len
    waist_z = pel_off + pel_len
    hip_y = D["hip_span"] / 2

    acc = Mass().add(mass_of("pelvis"), (0, 0, pel_off + specs["pelvis"]["cz"]))
    pel_vis = [("pelvis", f"0 0 {pel_off:.5f}", "0 0 0")]
    pel_col = shift(specs["pelvis"]["col"], pel_off)
    for sgn in (+1, -1):
        acc.add(ball_mass(r_hip), (0, sgn * hip_y, 0.0))
        pel_vis.append((ball(r_hip), f"0 {sgn * hip_y:.5f} 0", "0 0 0"))
        pel_col.append((ball(r_hip), f"0 {sgn * hip_y:.5f} 0", "0 0 0"))
    acc.add(ball_mass(r_waist), (0, 0, waist_z))
    pel_vis.append((ball(r_waist), f"0 0 {waist_z:.5f}", "0 0 0"))
    pel_col.append((ball(r_waist), f"0 0 {waist_z:.5f}", "0 0 0"))
    u.link("pelvis", visuals=pel_vis, collisions=pel_col, mass=acc.m,
           inertia=inertia_box(acc.m, pel_w * DEPTH_RATIO["pelvis"], pel_w, pel_len),
           com=acc.com)

    # ---- waist -> chest ---------------------------------------------------
    # Chest carries the two shoulder balls and the neck ball.
    ch_len, ch_w = D["chest"], D["chest_w"]
    sh_z = SHOULDER_FRAC_OF_CHEST * ch_len
    sh_y = D["shoulder_span"] / 2

    acc = Mass().add(mass_of("chest"), (0, 0, specs["chest"]["cz"]))
    ch_vis = [("chest", "0 0 0", "0 0 0")]
    ch_col = list(specs["chest"]["col"])
    for sgn in (+1, -1):
        acc.add(ball_mass(r_shldr), (0, sgn * sh_y, sh_z))
        ch_vis.append((ball(r_shldr), f"0 {sgn * sh_y:.5f} {sh_z:.5f}", "0 0 0"))
        ch_col.append((ball(r_shldr), f"0 {sgn * sh_y:.5f} {sh_z:.5f}", "0 0 0"))
    acc.add(ball_mass(r_neck), (0, 0, ch_len))
    ch_vis.append((ball(r_neck), f"0 0 {ch_len:.5f}", "0 0 0"))
    ch_col.append((ball(r_neck), f"0 0 {ch_len:.5f}", "0 0 0"))
    u.link("chest", visuals=ch_vis, collisions=ch_col, mass=acc.m,
           inertia=inertia_box(acc.m, ch_w * DEPTH_RATIO["chest"], ch_w, ch_len),
           com=acc.com)
    ball_chain(u, "pelvis", "chest", "waist", f"0 0 {waist_z:.5f}", "0 0 0", "waist")

    # ---- neck -> head -----------------------------------------------------
    # The neck joint sits at the centre of the neck ball (which belongs to the
    # chest), and the head's flat base is pulled down over it so the two read
    # as a ball in a socket rather than a head on a stalk.
    hd_len, hd_w = D["head"], D["head_w"]
    hd_off = -0.45 * r_neck
    m_hd = mass_of("head")
    u.link(
        "head",
        visuals=[("head", f"0 0 {hd_off:.5f}", "0 0 0")],
        collisions=shift(specs["head"]["col"], hd_off),
        mass=m_hd,
        inertia=inertia_box(m_hd, hd_w, hd_w, hd_len),
        com=f"0 0 {hd_off + specs['head']['cz']:.5f}",
    )
    # Full ball chain: the real neck is a ball joint, and without the Y axis
    # the head cannot nod -- which both the settling and the posed sampler
    # (head-tuck hard cases) need.
    ball_chain(u, "chest", "head", "neck", f"0 0 {ch_len:.5f}", "0 0 0", "neck")

    # ---- arms -------------------------------------------------------------
    # Each segment carries the ball at its DISTAL end, so the ball rides with
    # the parent and the child's proximal end sinks into it.
    ua_len, fa_len, hn_len = D["upper_arm"], D["forearm"], D["hand"]
    ua_d, fa_d, hn_w = D["upper_arm_d"], D["forearm_d"], D["hand_w"]

    def segment(name, mesh, length, width, depth, tip_r, tip_mesh_off=0.0):
        """A limb segment plus the joint ball at its far end."""
        acc = Mass().add(mass_of(mesh), (0, 0, specs[mesh]["cz"]))
        vis = [(mesh, "0 0 0", "0 0 0")]
        col = list(specs[mesh]["col"])
        if tip_r:
            acc.add(ball_mass(tip_r), (0, 0, length))
            vis.append((ball(tip_r), f"0 0 {length:.5f}", "0 0 0"))
            col.append((ball(tip_r), f"0 0 {length:.5f}", "0 0 0"))
        u.link(name, visuals=vis, collisions=col, mass=acc.m,
               inertia=inertia_box(acc.m, width, depth, length), com=acc.com)

    for side, sgn in (("l", +1), ("r", -1)):
        y = sgn * sh_y

        segment(f"upper_arm_{side}", "upper_arm", ua_len, ua_d, ua_d, r_elbow)
        # rpy pi about X flips local +Z to world -Z: the arm hangs down at
        # the zero pose.  The joint sits at the shoulder ball's centre.
        ball_chain(u, "chest", f"upper_arm_{side}", f"shoulder_{side}",
                   f"0 {y:.5f} {sh_z:.5f}", f"{math.pi:.5f} 0 0", "shoulder")

        segment(f"forearm_{side}", "forearm", fa_len, fa_d, fa_d, r_wrist)
        u.joint(f"elbow_{side}", f"upper_arm_{side}", f"forearm_{side}",
                xyz=f"0 0 {ua_len:.5f}", axis="0 1 0", limit=LIMITS["elbow"])

        m_hn = mass_of("hand")
        u.link(f"hand_{side}",
               visuals=[("hand", "0 0 0", "0 0 0")],
               collisions=list(specs["hand"]["col"]),
               com=f"0 0 {specs['hand']['cz']:.5f}",
               mass=m_hn,
               inertia=inertia_box(m_hn, hn_w, hn_w * FLATTEN["hand"], hn_len))
        u.joint(f"wrist_{side}", f"forearm_{side}", f"hand_{side}",
                xyz=f"0 0 {fa_len:.5f}", axis="1 0 0", limit=LIMITS["wrist"])

    # ---- legs -------------------------------------------------------------
    hip_z = 0.0  # pelvis link frame is already on the hip centre line
    th_len, sn_len, ft_len = D["thigh"], D["shin"], D["foot"]
    th_d, sn_d, ft_w = D["thigh_d"], D["shin_d"], D["foot_w"]

    for side, sgn in (("l", +1), ("r", -1)):
        y = sgn * hip_y

        segment(f"thigh_{side}", "thigh", th_len, th_d, th_d, r_knee)
        ball_chain(u, "pelvis", f"thigh_{side}", f"hip_{side}",
                   f"0 {y:.5f} {hip_z:.5f}", f"{math.pi:.5f} 0 0", "hip")

        segment(f"shin_{side}", "shin", sn_len, sn_d, sn_d, r_ankle)
        u.joint(f"knee_{side}", f"thigh_{side}", f"shin_{side}",
                xyz=f"0 0 {th_len:.5f}", axis="0 1 0", limit=LIMITS["knee"])

        m_ft = mass_of("foot")
        # Ry(pi/2) maps mesh +Z to local +X, i.e. the foot points forward.
        # The collision chain gets the same rotation via to_x().
        u.link(f"foot_{side}",
               visuals=[("foot", "0 0 0", f"0 {math.pi/2:.5f} 0")],
               collisions=to_x(specs["foot"]["col"]),
               com=f"{specs['foot']['cz']:.5f} 0 0",
               mass=m_ft,
               inertia=inertia_box(m_ft, ft_len, ft_w, ft_w * FLATTEN["foot"]))
        u.joint(f"ankle_{side}", f"shin_{side}", f"foot_{side}",
                xyz=f"0 0 {sn_len:.5f}", axis="0 1 0", limit=LIMITS["ankle"])

    return u


def measure_mass(urdf_path):
    """Total mass of the assembled model, kilograms.

    Read back from MuJoCo rather than summed here, so the joint balls and any
    future geometry are counted automatically instead of being forgotten.

    The pelvis has to be added back by hand: the URDF root link carries no
    joint, so MuJoCo merges it into worldbody and THROWS ITS MASS AWAY.  Left
    uncorrected this undercounts the figure by the single heaviest link, and
    the density solve below would then aim the wrong 119 g at the wrong body.
    """
    import re
    import mujoco
    m = mujoco.MjModel.from_xml_path(urdf_path)
    src = open(urdf_path).read()
    body = src.split('<link name="pelvis">', 1)[1]
    pelvis = float(re.search(r'<mass value="([^"]+)"', body).group(1))
    return float(m.body_subtreemass[0]) + pelvis


def measure_height(urdf_path):
    """True standing height of the generated visual geometry, metres.

    Measured from the mesh vertices at the zero pose rather than predicted
    from a length chain, because the chain does not know how far the foot
    blade actually drops below the ankle or how the joint collars overlap.
    """
    import mujoco
    import numpy as np
    m = mujoco.MjModel.from_xml_path(urdf_path)
    d = mujoco.MjData(m)
    mujoco.mj_forward(m, d)
    lo, hi = 1e9, -1e9
    for g in range(m.ngeom):
        if m.geom_type[g] != mujoco.mjtGeom.mjGEOM_MESH:
            continue
        mid = m.geom_dataid[g]
        v0, nv = m.mesh_vertadr[mid], m.mesh_vertnum[mid]
        V = m.mesh_vert[v0:v0 + nv].reshape(-1, 3)
        W = V @ d.geom_xmat[g].reshape(3, 3).T + d.geom_xpos[g]
        lo = min(lo, W[:, 2].min())
        hi = max(hi, W[:, 2].max())
    return hi - lo


def emit(out_dir, factor):
    mesh_dir = os.path.join(out_dir, "meshes")
    os.makedirs(mesh_dir, exist_ok=True)
    dims = scaled_dims(factor)
    specs = build_meshes(mesh_dir, dims)
    path = os.path.join(out_dir, "dummy.urdf")
    with open(path, "w") as f:
        f.write(build_urdf(specs, dims).dumps())
    return path, specs


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=os.path.dirname(os.path.abspath(__file__)))
    args = ap.parse_args()

    target = STANDING_HEIGHT_MM / 1000.0

    # Calibrate the global scale so the built geometry measures exactly
    # STANDING_HEIGHT_MM.  Iterated rather than solved in one step: the
    # shoulder span is deliberately held fixed while everything else scales,
    # so the height is not quite a linear function of the factor.
    factor, h1 = 1.0, None
    for _ in range(8):
        path, specs = emit(args.out, factor)
        h = measure_height(path)
        if h1 is None:
            h1 = h
        if abs(h - target) < 1e-5:      # 0.01 mm
            break
        factor *= target / h
    h2 = h

    # Mass is linear in density, so one step lands it exactly.
    global DENSITY
    m_now = measure_mass(path)
    DENSITY *= (TARGET_MASS_G / 1000.0) / m_now
    path, specs = emit(args.out, factor)
    m_final = measure_mass(path)

    real = (specs["pelvis"]["volume"] + specs["chest"]["volume"]
            + specs["head"]["volume"]
            + 2 * (specs["upper_arm"]["volume"] + specs["forearm"]["volume"]
                   + specs["hand"]["volume"] + specs["thigh"]["volume"]
                   + specs["shin"]["volume"] + specs["foot"]["volume"]))
    print(f"wrote {path}")
    print(f"  meshes        : {len(specs)} OBJ files in {args.out}/meshes")
    print(f"  calibration   : pass1 {h1*1000:.1f} mm -> factor {factor:.5f}")
    print(f"  height        : {h2*1000:.2f} mm  (target {STANDING_HEIGHT_MM:.1f})")
    print(f"  shoulder span : {specs and D['shoulder_span']*1000:.1f} mm (measured, unscaled)")
    print(f"  total mass    : {m_final*1000:.2f} g  (target {TARGET_MASS_G:.0f}, "
          f"effective density {DENSITY:.0f} kg/m^3)")
    print(f"  lathe volume  : {real*1e6:.1f} cm^3 in meshes, rest is joint balls")
    print("  NOTE mass is assumed, not weighed -- every calibrated frictionloss")
    print("       scales linearly with it (see dummy_params.WOOD_DENSITY).")


if __name__ == "__main__":
    main()
